// O(n) памяти: множество пройденных узлов
public bool HasCycleSet(ListNode head) {
    var seen = new HashSet<ListNode>();     // сравнение по ссылке
    for (var n = head; n != null; n = n.next)
        if (!seen.Add(n)) return true;      // узел уже был — цикл
    return false;
}

