public ListNode DetectCycle(ListNode head) {
    ListNode slow = head, fast = head;
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
        if (slow == fast) {                 // фаза 1: встреча, k кратно λ
            var p = head;
            while (p != slow) {             // фаза 2: по μ шагов с двух сторон
                p = p.next;
                slow = slow.next;
            }
            return p;                       // вход в цикл
        }
    }
    return null;                            // цикла нет
}

