// #287: n + 1 чисел от 1 до n, массив не менять, память O(1)
public int FindDuplicate(int[] nums) {
    int slow = 0, fast = 0;
    do { slow = nums[slow]; fast = nums[nums[fast]]; } while (slow != fast);
    int p = 0;
    while (p != slow) { p = nums[p]; slow = nums[slow]; }
    return p;                     // в повтор ведут две стрелки — это вход в цикл
}
